import{_ as t,o as r,a as o,b as i}from"./app.C41L12d5.js";const n="/ascendc.github.io/assets/kernel_sched_2.7rR4rwWp.png",c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"异构系统","link":"/guide/programming_guide/programming_model/heterogeneous_system"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/heterogeneous_system.md","filePath":"guide/programming_guide/programming_model/heterogeneous_system.md","lastUpdated":1787050286000}'),s={name:"guide/programming_guide/programming_model/heterogeneous_system.md"};function a(m,e,d,g,_,l){return r(),o("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>异构系统<span id="ZH-CN_TOPIC_0000002394061301"></span></h1><p>一个基于昇腾处理器的异构系统通常包含CPU与昇腾NPU。其中，CPU及其内存称为Host与Host Memory；NPU及其内存称为Device与Device Memory。</p><p>基于昇腾的应用程序通常包含两部分：一部分运行在Host CPU上，使用标准C/C++编程；另一部分运行在NPU上，使用Ascend C编程语言编写。运行在NPU上的代码称为<a href="./ai_core_simd_programming/kernel_function.html">核函数（Kernel）</a>，需由Host代码调用执行。此外，Host端需要通过CANN Runtime API完成以下操作：在Host Memory与Device Memory之间拷贝数据、启动NPU上的核函数（Kernel）、等待核函数（Kernel）执行完成等。Host代码与核函数（Kernel）可编写在同一个 .asc后缀文件中，由毕昇编译器完成异构编译。</p><p>为提升计算效率，NPU上通常有多个计算核并发执行，每个核一般处理不同的数据。每个NPU的计算核称为AI Core（AI处理器的计算核心）。传统上，AI Core遵循SIMD（Single Instruction Multiple Data，单指令多数据流）模型，通过一条指令同时操作多个数据实现并行计算。从Ascend 950PR/Ascend 950DT架构开始，作为SIMD的补充（主要用于辅助离散类矢量算子开发），AI Core也支持SIMT（Single Instruction Multiple Thread，单指令多线程）模型，通过一条指令驱动多个线程并行执行。</p><p>下图演示了运行在Host CPU上的代码通过调用CANN Runtime API将核函数（Kernel）下发到AI Core的流程。由于Host Memory与Device Memory拥有独立的内存空间，需要显式调用Runtime API进行数据传输。典型流程为：Host代码先将输入数据从Host Memory传输到Device Memory，随后启动Device侧核函数（Kernel）并等待其执行完成，最后将计算结果从Device Memory拷贝回Host Memory。</p><p><strong>图1</strong> 核函数（Kernel）调度示意图<span id="fig573916102285"></span><br><img src="'+n+'" alt="核函数（Kernel）调度示意图" width="520px"></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>关于Task/Stream等Runtime运行时管理的详细介绍，请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>。</p></div></article></div>',1)])])}const u=t(s,[["render",a]]);export{c as __pageData,u as default};
